import React from "react";
import ReactDOM from "react-dom/client";
import { BrowserRouter } from "react-router-dom";
import "bootstrap/dist/css/bootstrap.min.css";
import App from "./App";

ReactDOM.createRoot(document.getElementById("root")).render(
  <React.StrictMode>
    <BrowserRouter>
      <App />
    </BrowserRouter>
  </React.StrictMode>
);

import { useEffect, useState } from "react";
import { Routes, Route } from "react-router-dom";
import { Container, Row, Col } from "react-bootstrap";
import { API } from "./api";
import DepartmentList from "./components/DepartmentList";
import EmployeeList from "./components/EmployeeList";
import Dependents from "./components/Dependents";

// The page lives at http://localhost:3000 (route "/").
function CompanyPage() {
  const [employees, setEmployees] = useState([]);
  const [depId, setDepId] = useState(null);       // Q1 -> Q2
  const [selectedId, setSelectedId] = useState(null); // Q2 -> Q3

  useEffect(() => {
    fetch(`${API}/employees`).then((r) => r.json()).then(setEmployees);
  }, []);

  // Q3: after a successful PUT, replace the employee in the shared list
  const handleUpdated = (emp) =>
    setEmployees((list) => list.map((e) => (e.id === emp.id ? emp : e)));

  const selected = employees.find((e) => e.id === selectedId);

  return (
    <Container fluid className="py-3">
      <h1 className="text-center mb-4">COMPANY MANAGEMENT</h1>
      <Row>
        <Col md={3}>
          <DepartmentList employees={employees} onView={(id) => { setDepId(id); setSelectedId(null); }} activeId={depId} />
        </Col>
        <Col md={5}>
          {depId !== null && (
            <EmployeeList employees={employees.filter((e) => e.depId === depId)} onViewDependents={(e) => setSelectedId(e.id)} />
          )}
        </Col>
        <Col md={4}>
          {selected && <Dependents key={selected.id} employee={selected} onUpdated={handleUpdated} />}
        </Col>
      </Row>
    </Container>
  );
}

function App() {
  return (
    <Routes>
      <Route path="/" element={<CompanyPage />} />
    </Routes>
  );
}

export default App;

import { useEffect, useState } from "react";
import { Table, Button } from "react-bootstrap";
import { API } from "../api";

// Question 1 — Department List
function DepartmentList({ employees, onView, activeId }) {
  const [departments, setDepartments] = useState([]);

  useEffect(() => {
    fetch(`${API}/departments`).then((r) => r.json()).then(setDepartments);
  }, []);

  // manager full name: look up managerId in employees
  const managerName = (managerId) => {
    const m = employees.find((e) => String(e.id) === String(managerId));
    return m ? m.fullname : "";
  };

  return (
    <div>
      <h2>Department List</h2>
      <Table borderless id="department-table">
        <thead>
          <tr><th>DepName</th><th>Manager</th><th>Employees</th></tr>
        </thead>
        <tbody>
          {departments.map((d) => (
            <tr key={d.id} id={`dep-row-${d.id}`} className="department-row">
              <td>{d.depName}</td>
              <td className="manager-name">{managerName(d.managerId)}</td>
              <td>
                <Button className="view-btn" variant={activeId === d.id ? "success" : "info"} onClick={() => onView(d.id)}>View</Button>
              </td>
            </tr>
          ))}
        </tbody>
      </Table>
    </div>
  );
}

export default DepartmentList;

import { useEffect, useState } from "react";
import { Accordion, Table, Button } from "react-bootstrap";
import { API } from "../api";

// salary = floor(empSalary / 176 * workHours)
export const salaryOf = (emp, w) => Math.floor((emp.empSalary / 176) * w.workHours);
export const vnd = (n) => n.toLocaleString("vi-VN"); // 4261363 -> "4.261.363"

// Question 2 — employees of the chosen department + project work
function EmployeeList({ employees, onViewDependents }) {
  const [projects, setProjects] = useState([]);
  const [works, setWorks] = useState([]);

  useEffect(() => {
    fetch(`${API}/projects`).then((r) => r.json()).then(setProjects);
    fetch(`${API}/works`).then((r) => r.json()).then(setWorks);
  }, []);

  const projectName = (pid) => projects.find((p) => p.id === pid)?.projectName ?? "";

  return (
    <div>
      <h2>Employee List</h2>
      {employees.length === 0 && <p className="text-muted">No employees</p>}
      <Accordion id="employee-accordion" defaultActiveKey="0">
        {employees.map((emp, idx) => {
          const ws = works.filter((w) => w.employeeId === emp.id);
          const total = ws.reduce((s, w) => s + salaryOf(emp, w), 0);
          return (
            <Accordion.Item eventKey={String(idx)} key={emp.id} id={`emp-item-${emp.id}`} className="employee-item">
              <Accordion.Header className="employee-header">
                <b>#{idx + 1} - {emp.fullname}</b>
                {emp.supervisorId === null && <b className="text-primary">&nbsp;- Manager</b>}
              </Accordion.Header>
              <Accordion.Body>
                <ul>
                  <li>EmployeeId: {emp.id}</li>
                  <li>Gender: {emp.gender}</li>
                  <li>BirthDate: {emp.birthdate}</li>
                </ul>
                <Button className="view-dependents" onClick={() => onViewDependents(emp)}>View Dependents</Button>
                <h6 className="mt-3">Work on projects</h6>
                <Table borderless size="sm">
                  <thead>
                    <tr><th>WorkId</th><th>Project name</th><th>Work hours</th><th>Salary (VND)</th></tr>
                  </thead>
                  <tbody>
                    {ws.length === 0 && (<tr><td colSpan={4} className="text-muted">No projects</td></tr>)}
                    {ws.map((w) => (
                      <tr key={w.id} className="work-row">
                        <td>{w.id}</td>
                        <td>{projectName(w.projectId)}</td>
                        <td>{w.workHours}</td>
                        <td className="work-salary">{vnd(salaryOf(emp, w))}</td>
                      </tr>
                    ))}
                  </tbody>
                </Table>
                <div className="p-2 fw-bold projects-salary" style={{ background: "#cfe2ff" }}>
                  Projects Salary: {vnd(total)} VND
                </div>
              </Accordion.Body>
            </Accordion.Item>
          );
        })}
      </Accordion>
    </div>
  );
}

export default EmployeeList;

import { useState } from "react";
import { Table, Form, Button, Alert } from "react-bootstrap";
import { API } from "../api";

const RELATIONSHIPS = ["Wife", "Son", "Daughter", "Father", "Mother", "Father in law", "Mother in law"];

// today as "yyyy-mm-dd" in LOCAL time (an <input type="date"> value has the same format)
const todayStr = () => {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
};

// Question 3 — dependents of the selected employee (parent passes key={employee.id})
function Dependents({ employee, onUpdated }) {
  const [form, setForm] = useState({ fullname: "", birthdate: "", relationship: "" });
  const [errors, setErrors] = useState([]);
  const deps = employee.dependents || [];

  const validate = () => {
    const errs = [];
    if (!form.fullname.trim()) errs.push("Fullname is required");
    if (!form.birthdate) errs.push("Birthdate is required");
    else if (form.birthdate >= todayStr()) errs.push("Birthdate must be before today");
    if (!form.relationship) errs.push("Please choose a relationship");
    return errs;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const errs = validate();
    setErrors(errs);
    if (errs.length > 0) return;

    const newDep = {
      id: deps.reduce((m, d) => Math.max(m, Number(d.id) || 0), 0) + 1,
      name: form.fullname.trim(),
      birthdate: form.birthdate,
      relationship: form.relationship,
    };
    const updated = { ...employee, dependents: [...deps, newDep] };
    const res = await fetch(`${API}/employees/${employee.id}`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(updated),
    });
    onUpdated(await res.json()); // update the UI immediately
    setForm({ fullname: "", birthdate: "", relationship: "" });
  };

  return (
    <div id="dependents">
      <h2>Dependents List</h2>
      <p className="mb-1"><b>{employee.fullname}</b></p>
      {deps.length === 0 ? (
        <p className="text-danger no-dependents">No dependents</p>
      ) : (
        <Table borderless size="sm">
          <thead><tr><th>No.</th><th>Name</th><th>Birthdate</th><th>Relationship</th></tr></thead>
          <tbody>
            {deps.map((d, i) => (
              <tr key={d.id} className="dependent-row"><td>{i + 1}</td><td>{d.name}</td><td>{d.birthdate}</td><td>{d.relationship}</td></tr>
            ))}
          </tbody>
        </Table>
      )}

      <h4 className="mt-3">Add new dependents</h4>
      {errors.length > 0 && (
        <Alert variant="danger" className="error-list">
          <ul className="mb-0">{errors.map((m) => <li key={m}>{m}</li>)}</ul>
        </Alert>
      )}
      <Form noValidate onSubmit={handleSubmit}>
        <Form.Group className="mb-2">
          <Form.Label>Fullname</Form.Label>
          <Form.Control id="dep-fullname" value={form.fullname} onChange={(e) => setForm({ ...form, fullname: e.target.value })} />
        </Form.Group>
        <Form.Group className="mb-2">
          <Form.Label>Birthdate</Form.Label>
          <Form.Control id="dep-birthdate" type="date" value={form.birthdate} onChange={(e) => setForm({ ...form, birthdate: e.target.value })} />
        </Form.Group>
        <Form.Group className="mb-2">
          <Form.Label>Relationship</Form.Label>
          <Form.Select id="dep-relationship" value={form.relationship} onChange={(e) => setForm({ ...form, relationship: e.target.value })}>
            <option value="">--- Type of relationship ---</option>
            {RELATIONSHIPS.map((r) => <option key={r} value={r}>{r}</option>)}
          </Form.Select>
        </Form.Group>
        <Button id="dep-add" type="submit" variant="success">Add</Button>
      </Form>
    </div>
  );
}

export default Dependents;
